// TRANSFORM STEP
// Clean and enrich each row of data
const transformed = [];

for (const item of $input.all()) {
  const row = item.json;

  // Skip rows with missing critical fields
  if (!row.PassengerId || !row.Survived) continue;

  transformed.push({
    json: {
      id: parseInt(row.PassengerId),
      survived: row.Survived === '1',
      passenger_class: parseInt(row.Pclass) || null,
      name: row.Name ? row.Name.trim() : 'Unknown',
      gender: row.Sex ? row.Sex.toLowerCase() : null,
      age: row.Age ? parseFloat(row.Age) : null,
      fare: row.Fare ? parseFloat(row.Fare).toFixed(2) : null,
      embarked_from: {
        'C': 'Cherbourg',
        'Q': 'Queenstown',
        'S': 'Southampton'
      }[row.Embarked] || 'Unknown',
      family_size: (parseInt(row.SibSp) || 0) + (parseInt(row.Parch) || 0),
      processed_at: new Date().toISOString()
    }
  });
}

return transformed;

// VALIDATION STEP
// Filter out invalid records and tag valid ones
const valid = [];
const invalid = [];

for (const item of $input.all()) {
  const d = item.json;
  const errors = [];

  if (d.id === null || isNaN(d.id)) errors.push('Missing ID');
  if (d.passenger_class === null) errors.push('Missing class');
  if (d.age !== null && (d.age < 0 || d.age > 120)) errors.push('Invalid age');

  if (errors.length === 0) {
    valid.push({ json: { ...d, status: 'valid' } });
  } else {
    invalid.push({ json: { ...d, status: 'invalid', errors } });
  }
}

// Log summary
console.log(`Valid: ${valid.length} | Invalid: ${invalid.length}`);

// Return only valid records
return valid;

// AGGREGATE STEP
// Compute summary statistics
const items = $input.all();
const total = items.length;
const survived = items.filter(i => i.json.survived).length;
const avgAge = items
  .filter(i => i.json.age !== null)
  .reduce((sum, i) => sum + i.json.age, 0) / items.filter(i => i.json.age !== null).length;

const byClass = { 1: 0, 2: 0, 3: 0 };
items.forEach(i => { if (byClass[i.json.passenger_class] !== undefined) byClass[i.json.passenger_class]++; });

return [{
  json: {
    summary: {
      total_records: total,
      survived: survived,
      did_not_survive: total - survived,
      survival_rate_pct: ((survived / total) * 100).toFixed(1),
      average_age: avgAge.toFixed(1),
      passengers_by_class: byClass,
      generated_at: new Date().toISOString()
    },
    records: items.map(i => i.json)
  }
}];
